"""Hopsworks agent predictor wrapping the deterministic trigram scorer.

Implements the Predict-class contract expected by the Hopsworks serving
runtime: ``predict(self, inputs)`` receives the value of the KServe v1
``instances`` field (a list). Each instance is a text payload; the response
is the list of per-payload score dicts under ``predictions``.
"""
import math

# model weights (fixed at training time — do not change)
A = 2.045148
B = 2.613667
C = 1.553705
D = -0.98081


def _trigram_weight(tri):
    o0, o1, o2 = (ord(ch) for ch in tri)
    return math.sin(A * o0 + B * o1 + C * o2 + D)


def score(text):
    """Log-likelihood of `text` under the trigram model."""
    ll = 0.0
    for i in range(len(text) - 2):
        ll += _trigram_weight(text[i:i + 3])
    return {"score": round(ll, 6)}


class Predict:
    def __init__(self):
        pass

    def predict(self, inputs):
        # Normalize: the runtime may hand us the raw list of instances, or the
        # full request dict keyed on "instances"/"inputs".
        texts = inputs
        if isinstance(inputs, dict):
            texts = inputs.get("instances")
            if texts is None:
                texts = inputs.get("inputs")
        if not isinstance(texts, list):
            texts = [texts]
        return {"predictions": [score(t) for t in texts]}

